public static class NotesArt {
 static void Fit(Graphics g,string text,Rectangle r,int size,Color color,bool bold=false){using(var font=new Font(Scene.FontName,size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var brush=new SolidBrush(color))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap,LineAlignment=StringAlignment.Center})g.DrawString(text,font,brush,r,format);}
 public static void Widget(Graphics g,State state,int offset){var notes=NotesModel.Order(state.Notes);EditorArt.T(g,"Мои заметки",23,EditorArt.Text,23,65,true);EditorArt.Box(g,new Rectangle(303,64,34,26),AppTheme.Panel,7);EditorArt.Center(g,notes.Count.ToString(),new Rectangle(303,64,34,26),11,EditorArt.Accent,true);offset=Math.Max(0,Math.Min(offset,Math.Max(0,notes.Count-NotesModel.VisibleRows)));
 if(notes.Count==0){using(var p=new Pen(EditorArt.Accent,1.8f)){g.DrawRectangle(p,161,138,36,44);g.DrawLine(p,169,151,189,151);g.DrawLine(p,169,160,189,160);g.DrawLine(p,169,169,184,169);}EditorArt.Center(g,"Запиши первую мысль",new Rectangle(20,206,320,24),15,EditorArt.Text,true);EditorArt.Center(g,"Идеи, списки и планы — под рукой",new Rectangle(20,241,320,20),11,EditorArt.Muted);}else{for(int i=0;i<NotesModel.VisibleRows&&offset+i<notes.Count;i++){int y=NotesModel.RowTop+i*NotesModel.RowPitch;EditorArt.Box(g,new Rectangle(22,y,316,40),AppTheme.Panel,7);EditorArt.T(g,(offset+i+1).ToString("00"),10,EditorArt.Muted,33,y+15);Fit(g,notes[offset+i].Title,new Rectangle(62,y+4,248,32),12,EditorArt.Text,true);using(var pen=new Pen(EditorArt.Muted,1.4f)){g.DrawLine(pen,321,y+16,325,y+20);g.DrawLine(pen,325,y+20,321,y+24);}}if(notes.Count>NotesModel.VisibleRows){int thumb=Math.Max(20,220*NotesModel.VisibleRows/notes.Count);int y=NotesModel.RowTop+(220-thumb)*offset/(notes.Count-NotesModel.VisibleRows);EditorArt.Box(g,new Rectangle(343,y,2,thumb),Color.FromArgb(96,105,133),1);}}
 EditorArt.Box(g,new Rectangle(22,346,316,29),AppTheme.Panel,6);EditorArt.T(g,"+  Добавить заметку",12,EditorArt.Accent,35,354,true);}
 public static void EditorFrame(Graphics g,bool fresh){g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;EditorArt.T(g,fresh?"Новая заметка":"Заметка",25,EditorArt.Text,24,24,true);EditorArt.T(g,"Сохраняется на ПК и синхронизируется с аккаунтом",11,EditorArt.Muted,25,63);EditorArt.T(g,"НАЗВАНИЕ",10,EditorArt.Muted,25,105,true);EditorArt.T(g,"ТЕКСТ ЗАМЕТКИ",10,EditorArt.Muted,25,188,true);EditorArt.Field(g,new Rectangle(24,210,512,278));using(var pen=new Pen(EditorArt.Edge))g.DrawLine(pen,24,541,536,541);}
}
public static class NoteDialogs {
 public static bool Delete(Form owner,string title){using(var f=new ChromeForm("Удалить заметку",440,218)){f.Controls.Add(new Label{Text="Удалить заметку?",Font=Theme.F(16,FontStyle.Bold),ForeColor=EditorArt.Text,Bounds=new Rectangle(24,24,392,40)});f.Controls.Add(new Label{Text=title,AutoEllipsis=true,ForeColor=EditorArt.Muted,Bounds=new Rectangle(24,78,392,40)});f.Controls.Add(new SmoothButton("Оставить",new Rectangle(24,150,190,40),(s,e)=>{f.DialogResult=DialogResult.Cancel;f.Close();}));f.Controls.Add(new SmoothButton("Удалить",new Rectangle(226,150,190,40),(s,e)=>{f.DialogResult=DialogResult.Yes;f.Close();}){Primary=true});return f.ShowDialog(owner)==DialogResult.Yes;}}
 public static DialogResult Unsaved(Form owner){using(var f=new ChromeForm("Изменения в заметке",460,205)){f.Controls.Add(new Label{Text="Сохранить изменения?",Font=Theme.F(16,FontStyle.Bold),ForeColor=EditorArt.Text,Bounds=new Rectangle(24,24,412,40)});f.Controls.Add(new Label{Text="В заметке есть несохранённый текст.",ForeColor=EditorArt.Muted,Bounds=new Rectangle(24,76,412,30)});f.Controls.Add(new SmoothButton("Назад",new Rectangle(24,139,128,40),(s,e)=>{f.DialogResult=DialogResult.Cancel;f.Close();}));f.Controls.Add(new SmoothButton("Не сохранять",new Rectangle(162,139,128,40),(s,e)=>{f.DialogResult=DialogResult.No;f.Close();}));f.Controls.Add(new SmoothButton("Сохранить",new Rectangle(300,139,136,40),(s,e)=>{f.DialogResult=DialogResult.Yes;f.Close();}){Primary=true});return f.ShowDialog(owner);}}
}
public class NoteEditorForm:ChromeForm {
 Note original;DarkField title;TextBox body;Label status,counter;public Note Result;public bool DeleteRequested;
 public NoteEditorForm(Note note){original=note==null?null:CloudJson.Copy(note);Text="LumaDesk · Заметка";KeyPreview=true;SetContentSize(560,614);title=new DarkField(new Rectangle(24,128,512,42),note==null?"Новая заметка":note.Title,null);((TextBox)title.Input).MaxLength=140;title.Input.Text=note==null?"Новая заметка":note.Title;Controls.Add(title);body=new TextBox{Multiline=true,AcceptsReturn=true,AcceptsTab=true,WordWrap=true,ScrollBars=ScrollBars.Vertical,MaxLength=NotesModel.MaxBody,BorderStyle=BorderStyle.None,BackColor=EditorArt.Panel,ForeColor=EditorArt.Text,Font=Theme.F(11),Bounds=new Rectangle(38,224,484,250),Text=note==null?"":note.Body};body.AccessibleName="Текст заметки";Controls.Add(body);counter=new Label{Text="",ForeColor=EditorArt.Muted,Bounds=new Rectangle(380,499,156,23),TextAlign=ContentAlignment.MiddleRight,Font=Theme.F(9)};Controls.Add(counter);status=new Label{Text=note==null?"Ctrl+S — сохранить":UpdatedLabel(note),ForeColor=EditorArt.Muted,Bounds=new Rectangle(24,499,350,30),Font=Theme.F(9),AutoEllipsis=true};Controls.Add(status);body.TextChanged+=(s,e)=>Count();Count();if(note!=null)Controls.Add(new SmoothButton("Удалить",new Rectangle(24,561,112,36),(s,e)=>{if(NoteDialogs.Delete(this,title.Input.Text)){DeleteRequested=true;DialogResult=DialogResult.Yes;Close();}}));Controls.Add(new SmoothButton("Закрыть",new Rectangle(280,561,112,36),(s,e)=>Close()));Controls.Add(new SmoothButton("Сохранить",new Rectangle(404,561,132,36),(s,e)=>Save()){Primary=true});KeyDown+=(s,e)=>{if(e.Control&&e.KeyCode==Keys.S){e.Handled=true;e.SuppressKeyPress=true;Save();}};FormClosing+=(s,e)=>{if(DialogResult==DialogResult.OK||DeleteRequested||!Dirty())return;var decision=NoteDialogs.Unsaved(this);if(decision==DialogResult.Cancel){e.Cancel=true;return;}if(decision==DialogResult.Yes){if(!Build())e.Cancel=true;else DialogResult=DialogResult.OK;}};}
 static string UpdatedLabel(Note n){DateTime value;return DateTime.TryParse(n.UpdatedUtc,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out value)?"Изменено "+value.ToLocalTime().ToString("dd.MM · HH:mm"):"Ctrl+S — сохранить";}
 void Count(){counter.Text=body.Text.Length+" / "+NotesModel.MaxBody;}
 bool Dirty(){return original==null?title.Input.Text!="Новая заметка"||body.Text.Length>0:title.Input.Text!=original.Title||body.Text!=original.Body;}
 bool Build(){if(string.IsNullOrWhiteSpace(title.Input.Text)){status.Text="Напиши название заметки.";status.ForeColor=AppTheme.Error;title.Input.Focus();return false;}var candidate=new Note{Id=original==null?Guid.NewGuid().ToString("N"):original.Id,Title=title.Input.Text.Trim(),Body=body.Text,UpdatedUtc=original!=null&&original.Title==title.Input.Text.Trim()&&original.Body==body.Text?original.UpdatedUtc:DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)};try{var proposed=NotesModel.CommitPreview(Store.S.Notes,original,candidate);NotesModel.CheckQuota(Store.S,proposed);Result=candidate;return true;}catch(Exception error){status.Text=error.Message;status.ForeColor=AppTheme.Error;return false;}}
 void Save(){if(!Build())return;DialogResult=DialogResult.OK;Close();}
 protected override void OnShown(EventArgs e){base.OnShown(e);if(original==null){title.Input.Focus();title.Input.SelectAll();}else{body.Focus();body.Select(0,0);}}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var saved=e.Graphics.Save();e.Graphics.TranslateTransform(0,CaptionHeight);NotesArt.EditorFrame(e.Graphics,original==null);e.Graphics.Restore(saved);}
}
